import{_ as n,o as h,c as d,a3 as i}from"./chunks/framework.MGD2uYU7.js";const s=JSON.parse('{"title":"07 — Truyền thông trực tiếp: Ấn phẩm tại dự án & điểm tiếp xúc","description":"","frontmatter":{},"headers":[],"relativePath":"guide/07-truyen-thong-truc-tiep.md","filePath":"guide/07-truyen-thong-truc-tiep.md","lastUpdated":null}'),o={name:"guide/07-truyen-thong-truc-tiep.md"};function g(c,t,r,e,u,a){return h(),d("div",null,[...t[0]||(t[0]=[i('<h1 id="_07-—-truyen-thong-truc-tiep-an-pham-tai-du-an-điem-tiep-xuc" tabindex="-1">07 — Truyền thông trực tiếp: Ấn phẩm tại dự án &amp; điểm tiếp xúc <a class="header-anchor" href="#_07-—-truyen-thong-truc-tiep-an-pham-tai-du-an-điem-tiep-xuc" aria-label="Permalink to &quot;07 — Truyền thông trực tiếp: Ấn phẩm tại dự án &amp; điểm tiếp xúc&quot;">​</a></h1><p><strong>Dự án</strong>: Hệ thống phần mềm &amp; website cho CĐT An Phúc — dự án An Phúc Imperia <strong>Status</strong>: Draft gửi khách hàng rà soát — <strong>Updated</strong>: 2026-10-11 — <strong>Version</strong>: 2.0 <strong>Nguồn</strong>: Sheet <code>05_TRUYEN_THONG_TRUC_TIEP</code> (Google Sheet MAYogu × An Phúc)</p><blockquote><p>Bản đặc tả trung thực của sheet: bám sát từng hạng mục ấn phẩm, không tự thêm. Phần chưa rõ đánh dấu 🟡.</p></blockquote><hr><h2 id="_1-gioi-thieu-pham-vi-mang" tabindex="-1">1. Giới thiệu &amp; phạm vi mảng <a class="header-anchor" href="#_1-gioi-thieu-pham-vi-mang" aria-label="Permalink to &quot;1. Giới thiệu &amp; phạm vi mảng&quot;">​</a></h2><p>Sheet nguồn mang tiêu đề <strong>&quot;NGUỒN 04 – TRUYỀN THÔNG TRỰC TIẾP&quot;</strong>, phạm vi: <strong>&quot;Kênh trực tiếp tại dự án và các ấn phẩm/điểm tiếp xúc trực tiếp&quot;</strong>.</p><p><strong>Bản chất hạng mục</strong>: mảng này là <strong>ấn phẩm vật lý</strong> — thiết kế, in ấn, biển bảng, mô hình, tài liệu bán hàng bản cứng đặt tại dự án và các điểm tiếp xúc trực tiếp. <strong>Đây KHÔNG phải phần mềm</strong>; tài liệu mô tả đúng bản chất thiết kế/in ấn, không &quot;phần mềm hoá&quot; (ranh giới phạm vi toàn bộ tài liệu: doc <code>00</code> §5 — mảng F).</p><p><strong>Vai trò liên quan</strong>:</p><table tabindex="0"><thead><tr><th>Vai trò</th><th>Nội dung</th></tr></thead><tbody><tr><td><strong>CĐT (An Phúc)</strong></td><td>Chủ dự án — nguồn thông tin dự án/nhận diện thể hiện trên ấn phẩm; bên xác nhận nội dung trước khi triển khai (🟡 quy trình duyệt sheet chưa nêu — xem §6, OQ‑TTTT‑4)</td></tr><tr><td><strong>MAYogu</strong></td><td>Đơn vị thiết kế / phối hợp in ấn (theo ghi chú nhóm C — &quot;phối hợp in ấn phẩm; lắp đặt và hoàn thiện&quot;, mức 🔵 đề xuất)</td></tr></tbody></table><p><strong>Quan hệ với Phần mềm tổng / CRM</strong>: trong mô hình &quot;5 nguồn lead → 1 phần mềm tổng&quot; (doc <code>00</code> §4), mảng này là <strong>Nguồn 04</strong>. Lead / thông tin khách hàng thu được từ kênh trực tiếp sẽ <strong>nhập về Phần mềm tổng (CRM)</strong>, với phạm vi dữ liệu Nguồn 04 ghi tại doc <code>00</code>: <strong>&quot;Thông tin khách hàng, nguồn tiếp xúc, nội dung trao đổi&quot;</strong>. Nghiệp vụ lưu trữ/xử lý lead phía phần mềm: xem doc <code>02</code> (CRM); bức tranh chung luồng lead từ các kênh (trực tiếp + online) về CRM: xem doc <code>08</code>. Bản thân các ấn phẩm trong doc này <strong>không có cấu phần phần mềm</strong>.</p><hr><h2 id="_2-cau-truc-sheet-quy-uoc-nhan" tabindex="-1">2. Cấu trúc sheet &amp; quy ước nhãn <a class="header-anchor" href="#_2-cau-truc-sheet-quy-uoc-nhan" aria-label="Permalink to &quot;2. Cấu trúc sheet &amp; quy ước nhãn&quot;">​</a></h2><p>Sheet <code>05_TRUYEN_THONG_TRUC_TIEP</code> chia <strong>3 nhóm</strong>:</p><table tabindex="0"><thead><tr><th>Nhóm</th><th>Nội dung sheet</th><th>Nhãn</th><th>Chi tiết</th></tr></thead><tbody><tr><td><strong>A — Chuẩn hóa thông tin dự án</strong></td><td>Chỉ có tiêu đề nhóm, <strong>không có nội dung chi tiết</strong> (sheet để trống)</td><td>🟡 CẦN BỔ SUNG</td><td>§3</td></tr><tr><td><strong>B — Thiết kế ấn phẩm</strong></td><td><strong>12 hạng mục</strong>, header cột: <em>STT | Ấn phẩm | Kích thước đề xuất | Chất liệu / cấu tạo | Vị trí | Khung / đèn | Ghi chú</em></td><td>✅ nội dung sheet ghi rõ; kích thước ở mức 🔵 đề xuất; một số ô 🟡 để trống</td><td>§4</td></tr><tr><td><strong>C — Phối hợp triển khai</strong></td><td>Ghi chú: <em>&quot;Đề xuất tài liệu bán hàng; phối hợp in ấn phẩm; lắp đặt và hoàn thiện.&quot;</em></td><td>🔵 ĐỀ XUẤT chưa duyệt</td><td>§5</td></tr></tbody></table><p><strong>Nhãn trạng thái</strong> (quy ước chung toàn bộ tài liệu — doc <code>00</code> §2):</p><ul><li>✅ <strong>ĐÃ CHỐT</strong> — sheet khẳng định, có nguồn.</li><li>🟡 <strong>CẦN XÁC NHẬN / CẦN BỔ SUNG</strong> — sheet để trống hoặc chưa rõ; tài liệu <strong>không suy diễn</strong>.</li><li>🔵 <strong>ĐỀ XUẤT (chưa duyệt)</strong> — sheet ghi &quot;Đề xuất…&quot; / &quot;có thể…&quot; / &quot;dự kiến…&quot;; phải được CĐT xác nhận trước khi đưa vào thực hiện.</li></ul><p><strong>Mã hạng mục</strong>: 12 hạng mục nhóm B được đánh mã <strong>FR‑TTTT‑01 → FR‑TTTT‑12</strong> tương ứng STT 1 → 12 của sheet (quy ước định danh <code>FR-&lt;MOD&gt;-nn</code>, MOD = <code>TTTT</code> — doc <code>00</code> §7) để trích dẫn ID khi họp rà soát, tránh nhầm lẫn.</p><hr><h2 id="_3-nhom-a-—-chuan-hoa-thong-tin-du-an-🟡" tabindex="-1">3. Nhóm A — Chuẩn hóa thông tin dự án 🟡 <a class="header-anchor" href="#_3-nhom-a-—-chuan-hoa-thong-tin-du-an-🟡" aria-label="Permalink to &quot;3. Nhóm A — Chuẩn hóa thông tin dự án 🟡&quot;">​</a></h2><ul><li>Sheet <strong>chỉ nêu tiêu đề nhóm</strong> &quot;A | Chuẩn hóa thông tin dự án&quot;, <strong>không có nội dung chi tiết</strong>.</li><li>Theo nguyên tắc &quot;không bịa&quot;: tài liệu <strong>không suy diễn</strong> danh mục thông tin cần chuẩn hóa. Đánh dấu 🟡 <strong>CẦN BỔ SUNG</strong> — CĐT cần cung cấp bộ nội dung chuẩn hóa thông tin dự án dùng thống nhất trên các ấn phẩm (OQ‑TTTT‑1, §6).</li><li>Cơ sở liên hệ <strong>trong chính sheet</strong>: hạng mục 1 (Biển tên dự án) ghi các yếu tố xuất hiện trên ấn phẩm — <em>&quot;Tên dự án lớn; tên CĐT nhỏ bên dưới; logo CĐT hai bên&quot;</em>; hạng mục 9 ghi <em>&quot;thiết kế đồng bộ bộ nhận diện&quot;</em>. Như vậy nhóm B <strong>phụ thuộc</strong> vào thông tin chuẩn hóa của nhóm A (tên dự án, tên CĐT, logo/bộ nhận diện) — nhưng <strong>nội dung cụ thể phải do CĐT cung cấp</strong>, không tự điền (xem thêm OQ‑TTTT‑1, OQ‑TTTT‑2).</li></ul><hr><h2 id="_4-nhom-b-—-thiet-ke-an-pham-12-hang-muc" tabindex="-1">4. Nhóm B — Thiết kế ấn phẩm (12 hạng mục) <a class="header-anchor" href="#_4-nhom-b-—-thiet-ke-an-pham-12-hang-muc" aria-label="Permalink to &quot;4. Nhóm B — Thiết kế ấn phẩm (12 hạng mục)&quot;">​</a></h2><p>Bảng dưới đây <strong>sao chép trung thực 12 dòng của sheet</strong>, giữ nguyên header cột, ngôn từ và số liệu gốc (kích thước, chất liệu, vị trí, khung/đèn, ghi chú). Mã <code>FR‑TTTT‑nn</code> gắn theo STT sheet.</p><table tabindex="0"><thead><tr><th>STT</th><th>Ấn phẩm</th><th>Kích thước đề xuất</th><th>Chất liệu / cấu tạo</th><th>Vị trí</th><th>Khung / đèn</th><th>Ghi chú</th></tr></thead><tbody><tr><td>1 <em>(FR‑TTTT‑01)</em></td><td>Biển tên dự án</td><td>3,0 × 0,6 m</td><td>Alu ngoài trời + chữ nổi</td><td>Ngoài trời, tại cổng dự án</td><td>Khung kim loại, 2 mặt</td><td>Tên dự án lớn; tên CĐT nhỏ bên dưới; logo CĐT hai bên</td></tr><tr><td>2 <em>(FR‑TTTT‑02)</em></td><td>Hàng rào dự án</td><td>5,0 × 2,5 m/mảng</td><td>Bạt Hiflex ngoài trời, in UV</td><td>Ngoài trời</td><td>Gắn vào khung từng mảng</td><td>30 m hàng rào ≈ 6 mảng; mỗi mảng một chủ đề, tổng thể đồng bộ</td></tr><tr><td>3 <em>(FR‑TTTT‑03)</em></td><td>Biển tên VP đại diện dự án</td><td>Khoảng 2,5 × 3,0 m</td><td>Vải backlit xuyên sáng + khung hộp nhôm</td><td>Ngoài trời nhưng có mái/tầng 1</td><td>Có LED chiếu từ phía sau</td><td>Ưu tiên hình ảnh đẹp, sáng đều, nhận diện rõ cả ban ngày và ban đêm</td></tr><tr><td>4 <em>(FR‑TTTT‑04)</em></td><td>Khung ảnh trong phòng bán hàng</td><td>1,2–1,5 × 1,0 m/khung</td><td>Vải backlit mềm/xuyên sáng</td><td>Trong nhà</td><td>Khung hộp + LED bên trong</td><td>Dự kiến 6 khung; ưu tiên hiệu ứng ánh sáng sang, mềm</td></tr><tr><td>5 <em>(FR‑TTTT‑05)</em></td><td>Standee sự kiện</td><td>0,8 × 1,8 m</td><td>Vải/lụa in + khung tension</td><td>Trong/ngoài cửa dự án khi sự kiện</td><td>Không nhất thiết có đèn</td><td>Ưu tiên nhẹ, đẹp, dễ tháo lắp, hình ảnh cao cấp</td></tr><tr><td>6 <em>(FR‑TTTT‑06)</em></td><td>Mô hình 3D tổng thể</td><td>Khoảng 2,0 × 2,0 m</td><td>Mô hình kiến trúc chuyên nghiệp + đế</td><td>Trong phòng bán hàng/phòng tiếp khách</td><td>Có thể tích hợp LED</td><td>Mô hình lớn để thuyết trình với khách hàng và cơ quan quản lý</td></tr><tr><td>7 <em>(FR‑TTTT‑07)</em></td><td>Quyển giới thiệu dự án</td><td>20 × 29,7 cm (đóng quyển, khổ dọc)</td><td>Bìa giấy mỹ thuật/couche matt 250–300 gsm; ruột giấy matt 150–170 gsm</td><td>Trong phòng bán hàng, tiếp khách</td><td>🟡 <em>(sheet để trống)</em></td><td>Cán mờ; ép kim vàng Gold; dập nổi; bìa cắt laser hình ổ khóa; bo góc</td></tr><tr><td>8 <em>(FR‑TTTT‑08)</em></td><td>Tờ rời giới thiệu tổng quan dự án</td><td>A4 – 21 × 29,7 cm</td><td>Giấy matt 200–250 gsm</td><td>Phòng bán hàng / phát cho khách</td><td>🟡 <em>(sheet để trống)</em></td><td>Cán mờ; có thể ép kim vàng + dập nổi một số chi tiết</td></tr><tr><td>9 <em>(FR‑TTTT‑09)</em></td><td>Tờ rời giới thiệu Nhà ở xã hội</td><td>A4 – 21 × 29,7 cm</td><td>Giấy matt 200–250 gsm</td><td>Phòng bán hàng / khách hàng NOXH</td><td>🟡 <em>(sheet để trống)</em></td><td>Cán mờ; thiết kế đồng bộ bộ nhận diện</td></tr><tr><td>10 <em>(FR‑TTTT‑10)</em></td><td>Tờ rời giới thiệu Nhà ở thương mại</td><td>A4 – 21 × 29,7 cm</td><td>Giấy matt 200–250 gsm</td><td>Phòng bán hàng / khách hàng</td><td>🟡 <em>(sheet để trống)</em></td><td>Cán mờ; ép kim/dập nổi chọn lọc</td></tr><tr><td>11 <em>(FR‑TTTT‑11)</em></td><td>Tờ rời chính sách vay ngân hàng</td><td>A4 – 21 × 29,7 cm</td><td>Giấy matt 200–250 gsm</td><td>Phòng bán hàng / tư vấn khách hàng</td><td>🟡 <em>(sheet để trống)</em></td><td>Cán mờ; ưu tiên dễ đọc, có thể ép kim phần tiêu đề</td></tr><tr><td>12 <em>(FR‑TTTT‑12)</em></td><td>Card visit nhân viên</td><td>9 × 5,4 cm</td><td>Giấy mỹ thuật/couche matt 350 gsm</td><td>Nhân viên kinh doanh/đối ngoại</td><td>🟡 <em>(sheet để trống)</em></td><td>Cán mờ; ép kim Gold + dập nổi; bo góc nhẹ</td></tr></tbody></table><p><strong>Ghi chú đọc bảng (không làm thay đổi số liệu sheet):</strong></p><ol><li>Cột <strong>&quot;Kích thước đề xuất&quot;</strong> — đúng tên cột của sheet: các giá trị kích thước ở mức 🔵 <strong>đề xuất</strong>, cần CĐT xác nhận trước khi sản xuất/in. Các thông tin còn lại (chất liệu, vị trí, khung/đèn, ghi chú) là nội dung sheet đã ghi rõ (✅ mức sheet khẳng định).</li><li>Các từ <strong>&quot;Khoảng&quot;</strong> (mục 3, 6), <strong>&quot;Dự kiến&quot;</strong> (mục 4), <strong>&quot;có thể&quot;</strong> (mục 6, 8, 11), <strong>&quot;Không nhất thiết&quot;</strong> (mục 5) được <strong>giữ nguyên văn</strong> theo sheet — không chuyển thành số chính thức hay cam kết (nguyên tắc doc <code>00</code> §2).</li><li>Cột <strong>Khung / đèn</strong> của các mục 7–12: sheet <strong>để trống</strong> → đánh dấu 🟡, tài liệu <strong>không suy diễn</strong>.</li><li>Ghi chú mục 2 <strong>&quot;30 m hàng rào ≈ 6 mảng&quot;</strong> là ghi chú ước lượng của sheet — khối lượng thực tế cần xác nhận (🟡 — OQ‑TTTT‑3, §6).</li><li>Mục 4 ghi <strong>&quot;Dự kiến 6 khung&quot;</strong> — số lượng ở mức dự kiến, chưa chốt (🟡 — OQ‑TTTT‑3, §6).</li></ol><hr><h2 id="_5-nhom-c-—-phoi-hop-trien-khai-🔵" tabindex="-1">5. Nhóm C — Phối hợp triển khai 🔵 <a class="header-anchor" href="#_5-nhom-c-—-phoi-hop-trien-khai-🔵" aria-label="Permalink to &quot;5. Nhóm C — Phối hợp triển khai 🔵&quot;">​</a></h2><p>Ghi chú của sheet (nguyên văn):</p><blockquote><p>&quot;Đề xuất tài liệu bán hàng; phối hợp in ấn phẩm; lắp đặt và hoàn thiện.&quot;</p></blockquote><ul><li>Ghi chú bắt đầu bằng <strong>&quot;Đề xuất…&quot;</strong> → toàn bộ nhóm C mang nhãn 🔵 <strong>ĐỀ XUẤT, chưa được CĐT duyệt</strong>; chỉ triển khai sau khi CĐT xác nhận phạm vi.</li><li>Theo câu chữ của sheet, đề xuất gồm <strong>3 phần</strong>: <strong>(1)</strong> đề xuất tài liệu bán hàng; <strong>(2)</strong> phối hợp in ấn phẩm; <strong>(3)</strong> lắp đặt và hoàn thiện.</li><li>Sheet <strong>không mô tả chi tiết</strong> cách thực hiện, phân công trách nhiệm, tiến độ hay chi phí của từng phần — tài liệu <strong>không suy diễn</strong> thêm; các điểm chưa rõ được đẩy về doc <code>09</code> để theo dõi chung.</li></ul><hr><h2 id="_6-can-xac-nhan-oq-—-cđt-tra-loi-tai-lieu-khong-tu-tra-loi" tabindex="-1">6. Cần xác nhận (OQ) — CĐT trả lời, tài liệu KHÔNG tự trả lời <a class="header-anchor" href="#_6-can-xac-nhan-oq-—-cđt-tra-loi-tai-lieu-khong-tu-tra-loi" aria-label="Permalink to &quot;6. Cần xác nhận (OQ) — CĐT trả lời, tài liệu KHÔNG tự trả lời&quot;">​</a></h2><p>Các điểm 🟡 của mảng TTTT, tổng hợp theo quy ước doc <code>00</code> §2 (mọi chỗ chưa rõ đẩy về doc <code>09</code>):</p><table tabindex="0"><thead><tr><th>Mã</th><th>Nội dung cần xác nhận</th><th>Căn cứ (nguồn sheet/tài liệu)</th><th>Ai trả lời</th></tr></thead><tbody><tr><td><strong>OQ‑TTTT‑1</strong></td><td><strong>Nhóm A &quot;Chuẩn hóa thông tin dự án&quot; đang để trống</strong> — cần CĐT bổ sung nội dung bộ thông tin dự án chuẩn hóa dùng thống nhất trên ấn phẩm (tên dự án, tên CĐT, logo CĐT — các yếu tố đã xuất hiện trong ghi chú mục 1 nhóm B).</td><td>Sheet nhóm A không có nội dung chi tiết</td><td>CĐT</td></tr><tr><td><strong>OQ‑TTTT‑2</strong></td><td>Cần <strong>bộ nhận diện / logo file gốc</strong> để thiết kế đồng bộ các ấn phẩm (mục 1: &quot;logo CĐT hai bên&quot;; mục 9: &quot;thiết kế đồng bộ bộ nhận diện&quot;). Tham chiếu: doc <code>03</code> §1 &amp; §10 mục 1 (logo — &quot;cần file gốc&quot;), doc <code>09</code> (OQ‑7 bộ nhận diện: style/font/màu; OQ‑8 media chất lượng thiết kế, logo gốc).</td><td>Sheet nhóm B; doc <code>03</code>; doc <code>09</code></td><td>CĐT</td></tr><tr><td><strong>OQ‑TTTT‑3</strong></td><td><strong>Số lượng / định mức in từng ấn phẩm chưa chốt.</strong> Sheet mới có ghi chú ước lượng: mục 2 &quot;30 m hàng rào ≈ 6 mảng&quot; (cần xác nhận chiều dài hàng rào thực tế → số mảng thực tế); mục 4 &quot;Dự kiến 6 khung&quot;. Các mục còn lại <strong>không ghi số lượng</strong>.</td><td>Cột Ghi chú mục 2, 4; các mục khác trống số lượng</td><td>CĐT</td></tr><tr><td><strong>OQ‑TTTT‑4</strong></td><td><strong>Ai duyệt nội dung trước khi in?</strong> Sheet không nêu quy trình/người phê duyệt nội dung &amp; nhận diện trên từng ấn phẩm trước khi sản xuất.</td><td>Sheet không nêu</td><td>CĐT</td></tr></tbody></table><hr><h2 id="_7-lien-ket-tai-lieu-cross-reference" tabindex="-1">7. Liên kết tài liệu (cross-reference) <a class="header-anchor" href="#_7-lien-ket-tai-lieu-cross-reference" aria-label="Permalink to &quot;7. Liên kết tài liệu (cross-reference)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Doc</th><th>Liên hệ với mảng Truyền thông trực tiếp</th></tr></thead><tbody><tr><td><code>docs/02-phan-mem-tong-crm.md</code></td><td><strong>CRM / Phần mềm tổng</strong> — nơi lưu lead từ <strong>Nguồn 04</strong> (kênh trực tiếp): &quot;Thông tin khách hàng, nguồn tiếp xúc, nội dung trao đổi&quot; (doc <code>00</code> §4).</td></tr><tr><td><code>docs/03-web-chu-dau-tu.md</code></td><td><strong>Web CĐT</strong> — dùng chung <strong>bộ nhận diện &amp; media</strong>: yêu cầu logo file gốc, chuẩn hình ảnh/nhận diện; motif <strong>ổ khóa</strong> đã thống nhất ở concept brochure (doc <code>03</code> A.4/A.11) cũng xuất hiện tại mục 7 sheet này (&quot;bìa cắt laser hình ổ khóa&quot;).</td></tr><tr><td><code>docs/08-truyen-thong-online.md</code></td><td><strong>Truyền thông online (Nguồn 05)</strong> — kênh lead còn lại; bức tranh chung luồng lead từ các nguồn về CRM.</td></tr><tr><td><code>docs/09-open-questions.md</code></td><td><strong>Open questions</strong> — tổng hợp OQ‑TTTT‑1 → OQ‑TTTT‑4 (§6) cùng các mục liên quan (OQ‑7 bộ nhận diện, OQ‑8 media/logo).</td></tr></tbody></table><hr><h2 id="phu-luc-—-mapping-nhanh-sheet-↔-tai-lieu" tabindex="-1">Phụ lục — Mapping nhanh sheet ↔ tài liệu <a class="header-anchor" href="#phu-luc-—-mapping-nhanh-sheet-↔-tai-lieu" aria-label="Permalink to &quot;Phụ lục — Mapping nhanh sheet ↔ tài liệu&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Nhóm sheet</th><th>Mục tài liệu</th><th>Số hạng mục</th><th>Nhãn chính</th></tr></thead><tbody><tr><td>Tiêu đề / dòng phạm vi (&quot;NGUỒN 04 – TRUYỀN THÔNG TRỰC TIẾP&quot;)</td><td>§1</td><td>—</td><td>✅</td></tr><tr><td>A — Chuẩn hóa thông tin dự án</td><td>§3</td><td>0 (sheet để trống)</td><td>🟡</td></tr><tr><td>B — Thiết kế ấn phẩm</td><td>§4</td><td>12 (FR‑TTTT‑01 → FR‑TTTT‑12)</td><td>✅ nội dung; 🔵 kích thước đề xuất; 🟡 khung/đèn mục 7–12</td></tr><tr><td>C — Phối hợp triển khai</td><td>§5</td><td>1 ghi chú</td><td>🔵</td></tr><tr><td>Các điểm để trống / chưa rõ</td><td>§6 → doc <code>09</code></td><td>4 OQ</td><td>🟡</td></tr></tbody></table>',41)])])}const l=n(o,[["render",g]]);export{s as __pageData,l as default};
